/*
 Problem: 3702. Longest Subsequence With Non-Zero Bitwise XOR
 Language: cpp
 Runtime: 3 ms (38.91%)
 Memory: 171.2 MB (86.02%)
 Tags: Array, Bit Manipulation
*/
class Solution {
public:
    int longestSubsequence(vector<int>& nums) {
        int x = 0;
        bool nonZero = false;

        for (const auto& v : nums) {
            x ^= v;
            nonZero |= v != 0;
        }

        if (x != 0) return nums.size();
        return nonZero ? nums.size() - 1 : 0;
    }
};
